INSERT INTO ui_strings (key, locale, value) VALUES
 ('field.bt-25', 'en', 'Preceding invoice'),
 ('field.bt-25', 'de', 'Vorausgegangene Rechnung'),
 ('field.bt-26', 'en', 'Preceding invoice date'),
 ('field.bt-26', 'de', 'Datum der vorausgegangenen Rechnung'),
 ('apsetup.creditnotes', 'en', 'Credit Notes'),
 ('apsetup.creditnotes', 'de', 'Gutschriften'),
 ('apsetup.credit.sub', 'en', 'A credit note names the invoice it credits. When it is found (same supplier, that invoice number), this is what happens to that invoice. Every credit note is still approved as your process says, and exported to the ERP as a credit.'),
 ('apsetup.credit.sub', 'de', 'Eine Gutschrift nennt die Rechnung, die sie gutschreibt. Wird diese gefunden (gleicher Lieferant, diese Rechnungsnummer), geschieht mit ihr Folgendes. Jede Gutschrift wird weiterhin so freigegeben, wie Ihr Prozess es vorsieht, und als Gutschrift an das ERP exportiert.'),
 ('apsetup.credit.loadfailed', 'en', 'The credit note settings could not be loaded.'),
 ('apsetup.credit.loadfailed', 'de', 'Die Einstellungen für Gutschriften konnten nicht geladen werden.'),
 ('apsetup.credit.savefailed', 'en', 'The credit note settings could not be saved.'),
 ('apsetup.credit.savefailed', 'de', 'Die Einstellungen für Gutschriften konnten nicht gespeichert werden.'),
 ('apsetup.credit.fullUnpaid', 'en', 'A credit note that credits an unpaid invoice in full'),
 ('apsetup.credit.fullUnpaid', 'de', 'Eine Gutschrift über eine unbezahlte Rechnung in voller Höhe'),
 ('apsetup.credit.fullUnpaid.take_out', 'en', 'Take the invoice out of payment'),
 ('apsetup.credit.fullUnpaid.take_out', 'de', 'Die Rechnung aus der Zahlung nehmen'),
 ('apsetup.credit.fullUnpaid.take_out.help', 'en', 'It is marked Credited straight away and is not exported for payment. The supplier sees Credited in the network.'),
 ('apsetup.credit.fullUnpaid.take_out.help', 'de', 'Sie wird sofort als gutgeschrieben markiert und nicht zur Zahlung exportiert. Der Lieferant sieht im Netzwerk Gutgeschrieben.'),
 ('apsetup.credit.fullUnpaid.confirm', 'en', 'Ask AP to confirm first'),
 ('apsetup.credit.fullUnpaid.confirm', 'de', 'Zuerst von der Kreditorenbuchhaltung bestätigen lassen'),
 ('apsetup.credit.fullUnpaid.confirm.help', 'en', 'The invoice and the credit note are held, and the team below confirms the credit before the invoice is marked Credited.'),
 ('apsetup.credit.fullUnpaid.confirm.help', 'de', 'Rechnung und Gutschrift werden zurückgehalten, und das unten gewählte Team bestätigt die Gutschrift, bevor die Rechnung als gutgeschrieben markiert wird.'),
 ('apsetup.credit.partial', 'en', 'A credit note for part of an invoice'),
 ('apsetup.credit.partial', 'de', 'Eine Gutschrift über einen Teil einer Rechnung'),
 ('apsetup.credit.partial.pay', 'en', 'Pay the invoice, with the credit set against it'),
 ('apsetup.credit.partial.pay', 'de', 'Die Rechnung bezahlen, die Gutschrift wird verrechnet'),
 ('apsetup.credit.partial.pay.help', 'en', 'The invoice carries on. Both are exported, and the ERP nets the credit off the payment.'),
 ('apsetup.credit.partial.pay.help', 'de', 'Die Rechnung läuft weiter. Beide werden exportiert, und das ERP verrechnet die Gutschrift mit der Zahlung.'),
 ('apsetup.credit.partial.hold', 'en', 'Hold the invoice until AP confirms'),
 ('apsetup.credit.partial.hold', 'de', 'Die Rechnung bis zur Bestätigung zurückhalten'),
 ('apsetup.credit.partial.hold.help', 'en', 'As above, the team confirms before the invoice goes on to be paid.'),
 ('apsetup.credit.partial.hold.help', 'de', 'Wie oben: Das Team bestätigt, bevor die Rechnung bezahlt wird.'),
 ('apsetup.credit.notFound', 'en', 'A credit note whose invoice is not found'),
 ('apsetup.credit.notFound', 'de', 'Eine Gutschrift, deren Rechnung nicht gefunden wird'),
 ('apsetup.credit.notFound.review', 'en', 'Send it to AP to find the invoice'),
 ('apsetup.credit.notFound.review', 'de', 'Zur Kreditorenbuchhaltung, um die Rechnung zu finden'),
 ('apsetup.credit.notFound.review.help', 'en', 'It is held, with the reference the supplier gave, until the team says which invoice it credits, or none.'),
 ('apsetup.credit.notFound.review.help', 'de', 'Sie wird mit der Referenz des Lieferanten zurückgehalten, bis das Team sagt, welche Rechnung sie gutschreibt, oder keine.'),
 ('apsetup.credit.notFound.process', 'en', 'Process it as it is'),
 ('apsetup.credit.notFound.process', 'de', 'So verarbeiten, wie sie ist'),
 ('apsetup.credit.notFound.process.help', 'en', 'Approved and exported as a credit on the supplier''s account, against no invoice.'),
 ('apsetup.credit.notFound.process.help', 'de', 'Freigegeben und als Gutschrift auf das Lieferantenkonto exportiert, ohne Rechnung.'),
 ('apsetup.credit.paid', 'en', 'A credit note for an invoice already sent for payment'),
 ('apsetup.credit.paid', 'de', 'Eine Gutschrift für eine bereits zur Zahlung gegebene Rechnung'),
 ('apsetup.credit.paid.help', 'en', 'Always kept as a credit with the supplier and exported to the ERP as one. The invoice is marked Credited. Nothing to choose.'),
 ('apsetup.credit.paid.help', 'de', 'Immer als Gutschrift beim Lieferanten behalten und als solche an das ERP exportiert. Die Rechnung wird als gutgeschrieben markiert. Keine Auswahl nötig.'),
 ('apsetup.credit.team', 'en', 'Who confirms'),
 ('apsetup.credit.team', 'de', 'Wer bestätigt'),
 ('apsetup.credit.team.none', 'en', 'Administrators only'),
 ('apsetup.credit.team.none', 'de', 'Nur Administratoren'),
 ('apsetup.credit.team.help', 'en', 'Credits to confirm appear at the top of their Tasks.'),
 ('apsetup.credit.team.help', 'de', 'Zu bestätigende Gutschriften erscheinen oben in ihren Aufgaben.'),
 ('apsetup.credit.network', 'en', 'In the supplier network'),
 ('apsetup.credit.network', 'de', 'Im Lieferantennetzwerk'),
 ('apsetup.credit.network.allow', 'en', 'Suppliers may raise credit notes'),
 ('apsetup.credit.network.allow', 'de', 'Lieferanten dürfen Gutschriften erstellen'),
 ('apsetup.credit.network.help', 'en', 'From an invoice they sent you, in full or for some lines, as Peppol BIS Billing 3.0. Off: only credit notes from your other routes.'),
 ('apsetup.credit.network.help', 'de', 'Zu einer Rechnung, die sie Ihnen gesendet haben, ganz oder für einzelne Positionen, als Peppol BIS Billing 3.0. Aus: nur Gutschriften aus Ihren anderen Eingangswegen.'),
 ('credit.heading', 'en', 'Credits to confirm'),
 ('credit.heading', 'de', 'Zu bestätigende Gutschriften'),
 ('credit.sub', 'en', 'Credit notes waiting for you to say what happens to the invoice they credit. Until then, neither is exported.'),
 ('credit.sub', 'de', 'Gutschriften, bei denen Sie entscheiden, was mit der gutgeschriebenen Rechnung geschieht. Bis dahin wird keine von beiden exportiert.'),
